    return {"message": "vibe check passed"}

client = TestClient(app)

def test_vibe_route():
    # Since VIBE is not a standard HTTP method, we need to use the 'request' method of TestClient
    # which allows specifying any method.
    response = client.request("VIBE", "/vibe")
    assert response.status_code == 200
    assert response.json() == {"message": "vibe check passed"}

if __name__ == "__main__":
    try:
        test_vibe_route()
        print("Test passed!")
    except Exception as e:
        print(f"Test failed: {e}")
        import traceback
        traceback.print_exc()
        exit(1)
